contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount > 0, "need positive deposit");
        require(withdrawAmount > 0, "need positive withdraw");
        require(withdrawAmount <= depositAmount, "withdraw must not exceed deposited credit");
        require(address(this).balance >= depositAmount, "insufficient test balance");

        uint contractBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        c.deposit{value: depositAmount}();

        uint creditAfterDeposit = c.credit(address(this));
        require(creditAfterDeposit == depositAmount, "deposit credit mismatch");

        uint contractBalanceAfterDeposit = address(c).balance;
        require(contractBalanceAfterDeposit == contractBalanceBefore + depositAmount, "deposit balance mismatch");

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint creditAfterWithdraw = c.credit(address(this));
        uint contractBalanceAfterWithdraw = address(c).balance;
        uint testBalanceAfterWithdraw = address(this).balance;

        assert(
            !reverted &&
            withdrawAmount <= creditAfterDeposit &&
            creditAfterWithdraw == creditAfterDeposit - depositAmount &&
            contractBalanceAfterWithdraw == contractBalanceBefore &&
            testBalanceAfterWithdraw == testBalanceBefore - depositAmount + depositAmount
        );
    }

    receive() external payable {}
}

